/**
 * Applies pending SQL migrations generated by `npm run db:generate`.
 *
 * Run locally with `npm run db:migrate`; the app container runs a bundled
 * copy before starting the server. `MIGRATIONS_DIR` overrides the folder.
 */
import { existsSync } from "node:fs";
import path from "node:path";
import { drizzle } from "drizzle-orm/postgres-js";
import { migrate } from "drizzle-orm/postgres-js/migrator";
import postgres from "postgres";

async function main(): Promise<void> {
  const url = process.env.DATABASE_URL;
  if (!url) throw new Error("DATABASE_URL is not set");

  const migrationsFolder = path.resolve(
    process.env.MIGRATIONS_DIR ?? "src/server/db/migrations",
  );
  if (!existsSync(path.join(migrationsFolder, "meta", "_journal.json"))) {
    console.log(`No migrations found in ${migrationsFolder}; nothing to do.`);
    return;
  }

  const sql = postgres(url, { max: 1 });
  try {
    await migrate(drizzle(sql), { migrationsFolder });
    console.log("Migrations applied.");
  } finally {
    await sql.end();
  }
}

main().catch((error: unknown) => {
  console.error("Migration failed:", error);
  process.exit(1);
});
